('clm_short_8w_w8s3', 'r_clm', 8, '2', '5''', 55, 3, 1500, '[{"type": "Grad+", "unit": "% FTP", "power_start": 50.0, "power_end": 75.0, "duration_work": 360}, {"type": "CONST", "unit": "% FTP", "power_start": 85.0, "duration_work": 180}, {"type": "FRAC", "unit": "% FTP", "power_start": 120.0, "power_end": 60.0, "duration_work": 20, "duration_recup": 40, "repetitions": 3}, {"type": "CONST", "unit": "% FTP", "power_start": 60.0, "duration_work": 180}, {"type": "FRAC", "unit": "% FTP", "power_start": 105.0, "power_end": 55.0, "duration_work": 300, "duration_recup": 300, "repetitions": 2, "position": "prolongateurs", "position_recup": "cocottes"}, {"type": "CONST", "unit": "% FTP", "power_start": 70.0, "duration_work": 900, "position": "prolongateurs"}, {"type": "Grad-", "unit": "% FTP", "power_start": 65.0, "power_end": 45.0, "duration_work": 300}]'::jsonb, '[{"at": 890, "key": "clm_short_8w_lc_start", "duration": 12}, {"at": 1200, "key": "clm_short_8w_lc_up", "duration": 10}, {"at": 1490, "key": "clm_short_8w_lc_start", "duration": 12}, {"at": 1800, "key": "clm_short_8w_lc_up", "duration": 10}, {"at": 2090, "key": "clm_short_8w_lc_start", "duration": 12}]'::jsonb)
), built AS (
  SELECT s.*,
    (SELECT jsonb_object_agg(t.lang, wk.p || s.week || ' · ' || replace(replace(replace(replace(t.name, '{n}', s.n), '{d}', s.d), '{m}', s.minutes::text), ' 1×', ' '))
       FROM tpl t JOIN wk USING (lang) WHERE t.typ = s.typ) AS names,
    (SELECT jsonb_object_agg(t.lang, t.obj) FROM tpl t WHERE t.typ = s.typ) AS objs,
    (SELECT jsonb_object_agg(t.lang, t.info) FROM tpl t WHERE t.typ = s.typ) AS infos
  FROM s
)
UPDATE public.training_sessions ts SET
  session_json = jsonb_build_object('nom', b.names ->> 'fr', 'infos', '', 'duration', b.minutes, 'UnitDisplay', '% FTP', 'blocks', b.blocks),
  total_duration = b.minutes,
  live_comments = b.lc,
  translations_json = jsonb_build_object('name', b.names, 'objectif', b.objs, 'info', b.infos, 'live_comments', '{"clm_short_8w_lc_start": {"fr": "Passe en TT sur les prolongateurs : épaules relâchées, tiens jusqu''au bout du bloc.", "en": "Get into TT on the extensions: shoulders relaxed, hold until the end of the block.", "es": "Ponte en TT en los acoples: hombros relajados, aguanta hasta el final del bloque.", "it": "Mettiti in TT sulle protesi: spalle rilassate, tieni fino alla fine del blocco.", "de": "Ab in TT auf den Aufsatz: Schultern locker, bis zum Ende des Blocks halten.", "nl": "Ga in TT op de opzetstukken: schouders ontspannen, houd vol tot het einde van het blok.", "pt": "Vá para o TT no clipe: ombros relaxados, aguente até o fim do bloco.", "ja": "エアロバーでTTに：肩の力を抜き、ブロックの最後まで維持しよう。", "tr": "Uzatmalarda TT''ye geç: omuzlar gevşek, blok bitene kadar koru."}, "clm_short_8w_lc_up": {"fr": "Relève-toi et récupère. Prochain bloc en TT.", "en": "Sit up and recover. Next block in TT.", "es": "Incorpórate y recupera. Próximo bloque en TT.", "it": "Rialzati e recupera. Prossimo blocco in TT.", "de": "Aufrichten und erholen. Nächster Block in TT.", "nl": "Kom overeind en herstel. Volgend blok in TT.", "pt": "Levante o tronco e recupere. Próximo bloco em TT.", "ja": "上体を起こして回復。次のブロックはTTで。", "tr": "Doğrul ve toparlan. Sonraki blok TT''de."}, "clm_short_8w_lc_mid": {"fr": "Mi-bloc : vérifie ta tête et tes épaules, reste bas et relâché.", "en": "Halfway: check your head and shoulders, stay low and relaxed.", "es": "Mitad del bloque: revisa cabeza y hombros, sigue abajo y relajado.", "it": "Metà blocco: controlla testa e spalle, resta basso e rilassato.", "de": "Halbzeit: Kopf und Schultern prüfen, tief und locker bleiben.", "nl": "Halverwege: check je hoofd en schouders, blijf laag en ontspannen.", "pt": "Metade do bloco: confira cabeça e ombros, fique baixo e relaxado.", "ja": "ブロックの半分：頭と肩を確認、低くリラックスしたまま。", "tr": "Blok ortası: başını ve omuzlarını kontrol et, alçak ve gevşek kal."}, "clm_short_8w_lc_recup": {"fr": "Récupère en TT : reste sur les prolongateurs, ton cerveau associe la position au repos.", "en": "Recover in TT: stay on the extensions, your brain links the position with rest.", "es": "Recupera en TT: sigue en los acoples, tu cerebro asocia la posición al descanso.", "it": "Recupera in TT: resta sulle protesi, il cervello associa la posizione al riposo.", "de": "Erhole dich in TT: Bleib auf dem Aufsatz, dein Gehirn verbindet die Position mit Ruhe.", "nl": "Herstel in TT: blijf op de opzetstukken, je brein koppelt de houding aan rust.", "pt": "Recupere em TT: fique no clipe, seu cérebro associa a posição ao descanso.", "ja": "TTで回復：エアロバーに乗ったまま。脳がこの姿勢を休息と結びつけます。", "tr": "TT''de toparlan: uzatmalarda kal, beynin pozisyonu dinlenmeyle ilişkilendirir."}}'::jsonb),
  aero_duration_sec = b.aero,
  thumbnail_url = NULL
FROM built b
WHERE ts.name = b.skey || '_name';
